// ── Line Total Math (per line) ─────────────────────────────────────

describe('Cart Store — line total math', () => {
  beforeEach(() => createFreshStore())

  it('computes correct net total: quantity × unitPriceNet', () => {
    useCartStore.getState().addLineItem(mockPart, 3) // 500 × 3 = 1500

    const state = useCartStore.getState()
    expect(state.lineItems[0].lineTotalNet).toBe(1500)
  })

  it('computes correct gross total with VAT: net + (net × vatRateBps / 10000)', () => {
    // Standard VAT rate = 21% = 2100 basis points
    useCartStore.getState().addLineItem(mockPart, 3) // priceNet=500, qty=3 → net=1500

    const state = useCartStore.getState()
    const line = state.lineItems[0]
    // VAT: 1500 × 2100 / 10000 = 315
    expect(line.lineTotalVat).toBe(315)
    // Gross: 1500 + 315 = 1815
    expect(line.lineTotalGross).toBe(1815)
  })

  it('computes correct totals with discount (in basis points)', () => {
    useCartStore.getState().addLineItem(mockPart, 2) // priceNet=500, qty=2 → gross net = 1000
    const itemId = useCartStore.getState().lineItems[0].id
    // Apply 10% discount = 1000 bps: discounted per unit = 500 × (1 - 1000/10000) = 450
    // lineNetTotal = 450 × 2 = 900
    useCartStore.getState().applyDiscount(itemId, 1000)

    const state = useCartStore.getState()
    const line = state.lineItems[0]
    expect(line.discountPercent).toBe(1000) // 10% in bps
    expect(line.lineTotalNet).toBe(900) // 450 × 2
    // VAT: 900 × 2100 / 10000 = 189
    expect(line.lineTotalVat).toBe(189)
    // Gross: 900 + 189 = 1089
    expect(line.lineTotalGross).toBe(1089)
  })

  it('handles zero quantity line item totals', () => {
    useCartStore.getState().addLineItem(mockPart, 0) // should be removed or have 0 qty

    const state = useCartStore.getState()
    expect(state.lineItems).toHaveLength(0) // 0 qty removes the line
  })
})

// ── Overall Aggregation ────────────────────────────────────────────

describe('Cart Store — overall totals', () => {
  beforeEach(() => createFreshStore())

  it('aggregates subtotalNet across all line items', () => {
    useCartStore.getState().addLineItem(mockPart, 2) // 500 × 2 = 1000
    useCartStore.getState().addLineItem(mockPart2, 1) // 1500 × 1 = 1500

    const state = useCartStore.getState()
    expect(state.subtotalNet).toBe(2500) // 1000 + 1500
  })

  it('aggregates vatTotal across all line items', () => {
    // Standard VAT = 21%
    useCartStore.getState().addLineItem(mockPart, 2) // net=1000, vat=210
    useCartStore.getState().addLineItem(mockPart2, 1) // net=1500, vat=315

    const state = useCartStore.getState()
    expect(state.vatTotal).toBe(525) // 210 + 315
  })

  it('aggregates totalGross correctly: subtotalNet + vatTotal', () => {
    useCartStore.getState().addLineItem(mockPart, 2) // net=1000, gross=1210
    useCartStore.getState().addLineItem(mockPart2, 1) // net=1500, gross=1815

    const state = useCartStore.getState()
    expect(state.totalGross).toBe(3025) // 1210 + 1815
  })

  it('updates totals when line items change', () => {
    useCartStore.getState().addLineItem(mockPart, 1) // net=500, gross=605

    expect(useCartStore.getState().totalGross).toBe(605)

    useCartStore.getState().addLineItem(mockPart2, 1) // net=1500, gross=1815
    expect(useCartStore.getState().totalGross).toBe(2420) // 605 + 1815

    const itemId = useCartStore.getState().lineItems[0].id
    useCartStore.getState().removeLineItem(itemId)
    expect(useCartStore.getState().totalGross).toBe(1815)
  })

  it('resets totals when cart is cleared', () => {
    useCartStore.getState().addLineItem(mockPart, 2)
    expect(useCartStore.getState().totalGross).toBeGreaterThan(0)

    useCartStore.getState().clearCart()

    const state = useCartStore.getState()
    expect(state.lineItems).toHaveLength(0)
    expect(state.subtotalNet).toBe(0)
    expect(state.vatTotal).toBe(0)
    expect(state.totalGross).toBe(0)
  })
})

