// ── Change VAT Rate ────────────────────────────────────────────────

describe('Cart Store — changeVatRate', () => {
  beforeEach(() => createFreshStore())

  it('changes the VAT rate on a line item', () => {
    useCartStore.getState().addLineItem(mockPart) // defaults to vat-standard (21%)

    const state = useCartStore.getState()
    expect(state.lineItems[0].vatRateId).toBe('vat-standard')

    const itemId = state.lineItems[0].id
    useCartStore.getState().changeVatRate(itemId, 'vat-reduced')

    const newState = useCartStore.getState()
    expect(newState.lineItems[0].vatRateId).toBe('vat-reduced')
  })

  it('recalculates line totals when VAT rate changes to reduced (6%)', () => {
    // priceNet=500, qty=3 → net=1500
    useCartStore.getState().addLineItem(mockPart, 3)

    const state = useCartStore.getState()
    expect(state.lineItems[0].vatRateId).toBe('vat-standard')
    // Standard VAT: 1500 × 2100 / 10000 = 315
    expect(state.lineItems[0].lineTotalVat).toBe(315)
    expect(state.lineItems[0].lineTotalGross).toBe(1815)

    // Change to reduced VAT (6%)
    const itemId = state.lineItems[0].id
    useCartStore.getState().changeVatRate(itemId, 'vat-reduced')

    const newState = useCartStore.getState()
    // Reduced VAT: 1500 × 600 / 10000 = 90
    expect(newState.lineItems[0].lineTotalVat).toBe(90)
    expect(newState.lineItems[0].lineTotalGross).toBe(1590)
  })

  it('recalculates line totals when VAT rate changes to zero (0%)', () => {
    useCartStore.getState().addLineItem(mockPart, 2) // priceNet=500, qty=2 → net=1000

    const state = useCartStore.getState()
    expect(state.lineItems[0].lineTotalVat).toBe(210) // 1000 × 21%

    const itemId = state.lineItems[0].id
    useCartStore.getState().changeVatRate(itemId, 'vat-zero')

    const newState = useCartStore.getState()
    expect(newState.lineItems[0].lineTotalVat).toBe(0)
    expect(newState.lineItems[0].lineTotalGross).toBe(1000)
  })

  it('does not affect other line items when changing VAT rate', () => {
    useCartStore.getState().addLineItem(mockPart, 1) // part-001
    useCartStore.getState().addLineItem(mockPart2, 1) // part-002

    const state = useCartStore.getState()
    expect(state.lineItems[0].vatRateId).toBe('vat-standard')
    expect(state.lineItems[1].vatRateId).toBe('vat-standard')

    const itemId = state.lineItems[0].id
    useCartStore.getState().changeVatRate(itemId, 'vat-reduced')

    const newState = useCartStore.getState()
    expect(newState.lineItems[0].vatRateId).toBe('vat-reduced')
    // part-002 should be unchanged
    expect(newState.lineItems[1].vatRateId).toBe('vat-standard')
  })

  it('updates aggregated totals when VAT rate changes', () => {
    useCartStore.getState().addLineItem(mockPart, 2) // net=1000, vat-std → vat=210, gross=1210
    useCartStore.getState().addLineItem(mockPart2, 1) // net=1500, vat-std → vat=315, gross=1815

    const state = useCartStore.getState()
    expect(state.vatTotal).toBe(525) // 210 + 315
    expect(state.totalGross).toBe(3025)

    // Change first item to zero VAT
    const itemId = state.lineItems[0].id
    useCartStore.getState().changeVatRate(itemId, 'vat-zero')

    const newState = useCartStore.getState()
    // First item: net=1000, vat=0, gross=1000
    // Second item unchanged: net=1500, vat=315, gross=1815
    expect(newState.vatTotal).toBe(315) // 0 + 315
    expect(newState.totalGross).toBe(2815) // 1000 + 1815
  })

  it('does nothing when changing VAT rate on non-existent id', () => {
    useCartStore.getState().addLineItem(mockPart)

    const state = useCartStore.getState()
    expect(state.lineItems).toHaveLength(1)
    expect(state.lineItems[0].vatRateId).toBe('vat-standard')

    useCartStore.getState().changeVatRate('nonexistent', 'vat-zero')

    const newState = useCartStore.getState()
    // Should be unchanged
    expect(newState.lineItems).toHaveLength(1)
    expect(newState.lineItems[0].vatRateId).toBe('vat-standard')
  })

  it('checkout payload reflects updated VAT rate', () => {
    useCartStore.getState().addLineItem(mockPart, 2)

    // Change to reduced VAT before checkout
    const itemId = useCartStore.getState().lineItems[0].id
    useCartStore.getState().changeVatRate(itemId, 'vat-reduced')

    const payload = useCartStore.getState().getCheckoutPayload()

    expect(payload.lineItems[0].vatRateId).toBe('vat-reduced')
  })
})

